import{_ as a,o as t,c as i,a5 as s}from"./chunks/framework.BwlBv862.js";const u=JSON.parse('{"title":"提交范围明确的贡献","description":"","frontmatter":{"title":"提交范围明确的贡献","docId":"developer.contributing","translationKey":"developer.contributing","locale":"zh","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2e0522178ebee69ea5eb20fec3c0ec586f13950c51d658cb3a21843536b2f9f9","translationRevision":"69b624eecbaba67197d3daa99516e6f19328d612ebec2e115f69d9401430739c","order":230},"headers":[],"relativePath":"zh/developer/contributing.md","filePath":"zh/developer/contributing.md","lastUpdated":1794611623000}'),n={name:"zh/developer/contributing.md"};function r(o,e,l,d,h,c){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="contributing-focused-changes" tabindex="-1">提交范围明确的贡献 <a class="header-anchor" href="#contributing-focused-changes" aria-label="Permalink to &quot;提交范围明确的贡献 {#contributing-focused-changes}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>准备其他贡献者可以审查和验证的改动。编辑前，阅读仓库的 <a href="https://github.com/nglmercer/TikTools-app/blob/remake/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a>、适用的 <code>AGENTS.md</code> 及<a href="./setup.html">环境设置</a>。使用 Bun 1.4.4，必要时使用 Rust 1.95 或更新版本、已提交锁文件，以及基于预期目标的分支。</p><h2 id="define-and-implement-the-change" tabindex="-1">定义并实现改动 <a class="header-anchor" href="#define-and-implement-the-change" aria-label="Permalink to &quot;定义并实现改动 {#define-and-implement-the-change}&quot;">​</a></h2><ol><li>检查 <code>git status</code>，保留他人负责的工作。补丁中不要包含生成资源、凭据和本地数据库。</li><li>遵循当前源码职责：服务行为属于 Rust 核心，契约属于 Control API 模块，SDK 覆盖属于类型化客户端，展示遵循<a href="./frontend.html">前端分层图</a>。</li><li>契约变化时，同时更新规范定义并重新生成派生输出。不要手工维护另一份完整 RPC 或事件 schema 表。</li><li>插件专属实现保留在各自外部插件包；通用宿主代码应发现清单，而非导入特定插件。</li><li>说明具体触发条件及最终行为，包括尚未完成或实验性的路径。</li></ol><h2 id="validate-proportionately" tabindex="-1">按影响范围验证 <a class="header-anchor" href="#validate-proportionately" aria-label="Permalink to &quot;按影响范围验证 {#validate-proportionately}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-lint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div><p>原生实现变化还需要适用的 Rust 格式、lint、测试及必需 CI 门控。仅文档改动应使用文档检查，并审查命令和源码链接，不应声称通过原生运行时验收。项目任务运行器负责支持的入口；特定原生目标参数使用 Cargo 透传。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;预期结果与状态 {#expected-result-and-status}&quot;">​</a></h2><p>审查应包含范围明确的源码变更、有意义的验证证据和如实说明的限制。仓库策略面向合入 <code>remake</code> 的拉取请求；发布标签由维护者控制。贡献说明已提供，但分支保护和远程检查配置是管理员职责，并非 Markdown 页面能保证。</p><h2 id="recover" tabindex="-1">恢复方法 <a class="header-anchor" href="#recover" aria-label="Permalink to &quot;恢复方法 {#recover}&quot;">​</a></h2><p>缺少依赖或平台库导致验证失败时，应报告并修复环境，不要削弱检查。生成文件偏离时，从其权威来源重新生成并检查差异。绝不要发布会话 Cookie、密钥、凭据或未脱敏事件抓取数据。源码与旧设计不一致时，说明差异，并以当前实现编写公开指南。不要覆盖其他所有者尚未完成的文件，只为让大范围清理看起来一致。</p><h2 id="operational-details" tabindex="-1">运行细节 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;运行细节 {#operational-details}&quot;">​</a></h2><p>审核标记含义分开：<code>sourceRevision</code> 是当前英文正文哈希，<code>translationRevision</code> 是本篇本地化正文哈希（移除 frontmatter 并去除首尾空白）。审核源文及全部译文后，运行 <code>bun docs/scripts/record-review.ts developer/example.md</code>。随后修改任一正文会使相应标记失效。这只能检测漂移，不能证明审核者身份或语义一致；应明确比较命令、RPC/环境标识符、payload 键、限制、启用/恢复步骤及否定表达。完整翻译说明并保留技术指令。</p><p>拆分迁移时，在映射中记录每个原主题/标题及具体替代目标，指向特定章节时包含片段。检查器验证文件、片段及历史原始字节；主题覆盖仍须编辑审核。不要修改历史原文及 provenance 来让验证通过。</p>`,15)])])}const k=a(n,[["render",r]]);export{u as __pageData,k as default};
